-- 烟厂地块演示导入：场地、2台设备、8个杆子、5758条模拟运行记录。
-- 仅写入原有业务表，不创建普通表/临时表，不修改字段、索引或外键。
-- 所有业务表明确限定为jdf；库名不同时替换所有 `jdf`。完整执行，遇错停止并ROLLBACK。
-- 原site.info字段用于标记本批次演示数据；同名场地无此标记时不写入。
-- 设备或杆子已绑定其他场地时不写入；末尾import_allowed=1才表示导入完成。
-- 优先场地ID2000005；占用时自动分配新ID，末尾输出实际编号。
-- 重复导入按设备名+随机时间跳过已有日志，当前模拟参数会重新同步。
-- 模拟记录2026-09-15至2026-10-14，当前在线、水位100%、角度朝围栏内。
-- 配套回滚文件：yanchang_site_rollback.sql。

SET NAMES utf8mb4;

SET time_zone = '+08:00';

START TRANSACTION;

SET @jdf_site_id = COALESCE((SELECT id FROM `jdf`.`site` WHERE name='烟厂地块' LIMIT 1), IF(NOT EXISTS(SELECT 1 FROM `jdf`.`site` WHERE id=2000005),2000005,(SELECT COALESCE(MAX(id),2000000)+1 FROM `jdf`.`site`)));

SET @jdf_valid = NOT EXISTS (SELECT 1 FROM `jdf`.`site` WHERE name='烟厂地块' AND COALESCE(info,'') <> '烟厂地块模拟演示_20261014') AND NOT EXISTS (SELECT 1 FROM `jdf`.`device` WHERE device_name IN ('3193532260402424', '3193232251100970') AND site_id <> @jdf_site_id) AND NOT EXISTS (SELECT 1 FROM `jdf`.`pole` WHERE site_id=@jdf_site_id AND (device_name NOT IN ('3193532260402424', '3193232251100970') OR device_name IS NULL));

