) d
WHERE @jdf_valid AND NOT EXISTS (SELECT 1 FROM `jdf`.`device_record` r WHERE r.device_name=d.device_name AND r.timestamp=d.timestamp);

COMMIT;

SELECT @jdf_valid AS import_allowed, IF(@jdf_valid,'导入成功','未写入：同名场地未标记为本次演示，或设备/杆子已有其他归属') AS result, @jdf_site_id AS imported_site_id;

SELECT device_name,alias,status,pm2_5,pm10,pitch_angle,horizontal_angle,water_in_status_100,timestamp FROM `jdf`.`device` WHERE @jdf_valid AND site_id=@jdf_site_id;

SELECT pole_name,device_name,longitude,latitude FROM `jdf`.`pole` WHERE @jdf_valid AND site_id=@jdf_site_id ORDER BY pole_name;

SELECT device_name,COUNT(*) AS record_count,MIN(timestamp) AS first_record,MAX(timestamp) AS latest_record FROM `jdf`.`device_record` WHERE @jdf_valid AND device_name IN ('3193532260402424', '3193232251100970') GROUP BY device_name;
